// Pools.fun test image endpoint.
//
// Serves the duck PNG that is referenced by the image field in the
// static /pools/metadata JSON. Image is embedded as base64 to avoid
// extra file lookups and to keep the function self-contained.

export const config = {
  runtime: "edge",
};

const DUCK_PNG_BASE64 = "";

const IMAGE_BYTES = Uint8Array.from(atob(DUCK_PNG_BASE64), (c) => c.charCodeAt(0));

export default function handler(): Response {
  return new Response(IMAGE_BYTES, {
    status: 200,
    headers: {
      "Content-Type": "image/png",
      "Cache-Control": "public, s-maxage=300, max-age=60",
      "Access-Control-Allow-Origin": "*",
      "Content-Length": IMAGE_BYTES.length.toString(),
    },
  });
}
